export function buildPmTextIndex(t){const e=[];let n="";t.descendants((t,r)=>{if(t.isText){const s=n.length;n+=t.text;e.push({pos:r,start:s,end:s+t.text.length})}return true});return{text:n,segments:e}}export function pmPositionToOffset(t,e){if(t.length===0){return 0}for(const n of t){const t=n.pos+(n.end-n.start);if(e<n.pos){return n.start}if(e<=t){return n.start+(e-n.pos)}}return t[t.length-1].end}